// Helper function to get relative path
func getRelativePath(fullPath string, basePath string) string {
	// If the full path is already relative, return it as is
	if !strings.HasPrefix(fullPath, "/") {
		return fullPath
	}

	// If base path is empty, just return the filename
	if basePath == "" {
		return filepath.Base(fullPath)
	}

	// Try to make the path relative to the base path
	relPath, err := filepath.Rel(basePath, fullPath)
	if err != nil {
		// If we can't make it relative, return just the filename
		return filepath.Base(fullPath)
	}
	return relPath
}

// Helper function to get relative image path
func getRelativeImagePath(outputPath string, exportFolderPath string) string {
	// Remove the export folder path prefix and any leading slashes
	relativePath := strings.TrimPrefix(outputPath, exportFolderPath)
	return strings.TrimPrefix(relativePath, "/")
}

// Helper function to sort STL results by name first, then alphabetically
func sortSTLResults(results []models.GenerateSTLResult) []models.GenerateSTLResult {
	sorted := make([]models.GenerateSTLResult, len(results))
	copy(sorted, results)
	sort.Slice(sorted, func(i, j int) bool {
		// First sort by name
		if sorted[i].InstanceConfig.Name != sorted[j].InstanceConfig.Name {
			return sorted[i].InstanceConfig.Name < sorted[j].InstanceConfig.Name
		}
		// Then sort alphabetically by output path
		return sorted[i].OutputPath < sorted[j].OutputPath
	})
	return sorted
}

